from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(2, 7))
    a = draw(st.lists(st.integers(1, 20), min_size=n, max_size=n, unique=True))
    c = draw(st.lists(st.integers(1, 20), min_size=n, max_size=n, unique=True))
    lines = [str(n)] + [f"{a[i]} {c[i]}" for i in range(n)]
    return "\n".join(lines) + "\n"

def validate(inp):
    t = inp.split()
    if len(t) < 1:
        return False
    n = int(t[0])
    if not (2 <= n <= 2 * 10**5):
        return False
    if len(t) != 1 + 2 * n:
        return False
    vals = [int(x) for x in t[1:]]
    A = vals[0::2]
    C = vals[1::2]
    if any(not (1 <= x <= 10**9) for x in A + C):
        return False
    if len(set(A)) != n or len(set(C)) != n:
        return False
    return True

def ref(inp):
    t = inp.split()
    n = int(t[0])
    vals = [int(x) for x in t[1:]]
    A = vals[0::2]
    C = vals[1::2]
    res = []
    for i in range(n):
        dominated = False
        for j in range(n):
            if A[j] > A[i] and C[j] < C[i]:
                dominated = True
                break
        if not dominated:
            res.append(i + 1)
    return f"{len(res)}\n{' '.join(map(str, res))}\n"
